void *yyalloc (yy_size_t  size , yyscan_t yyscanner)
{
	struct yyguts_t * yyg = (struct yyguts_t*)yyscanner;
	(void)yyg;
	return ct_alloc(size);
}

void *yyrealloc  (void * ptr, yy_size_t  size , yyscan_t yyscanner)
{
	struct yyguts_t * yyg = (struct yyguts_t*)yyscanner;
	(void)yyg;

	/* The cast to (char *) in the following accommodates both
	 * implementations that use char* generic pointers, and those
	 * that use void* generic pointers.  It works with the latter
	 * because both ANSI C and C++ allow castless assignment from
	 * any pointer type to void*, and deal with argument conversions
	 * as though doing an assignment.
	 */
	return ct_grow(ptr, size);
}

void yyfree (void * ptr , yyscan_t yyscanner)
{
	struct yyguts_t * yyg = (struct yyguts_t*)yyscanner;
	(void)yyg;
	ct_drop( (char *) ptr );	/* see yyrealloc() for (char *) cast */
}

#define YYTABLES_NAME "yytables"

/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
void sno_error_voice(int code, const char *text, int ln) {
    extern void core_error_voice_at(int code, const char *msg, const char *file, long line, long stno);
    if (sno_err_quiet) { sno_err_capturef("%s", text); sno_nerrors++; return; }
    core_error_voice_at(code, text, sno_frame_file(), ln, 0);
    sno_nerrors++;
}
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
void sno_error(int ln, const char *fmt, ...) {
    va_list ap;
    if (sno_err_quiet) {
        va_start(ap,fmt); sno_err_vcapture(fmt,ap); va_end(ap);
        sno_nerrors++;
        return;
    }
    fprintf(stderr,"snobol4:%d: error: ",ln);
    va_start(ap,fmt); vfprintf(stderr,fmt,ap); va_end(ap);
    fputc('\n',stderr);
    sno_nerrors++;
}
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
void sno_add_include_dir(const char *d) {
    if (n_inc >= inc_dirs_cap) { inc_dirs_cap = inc_dirs_cap ? inc_dirs_cap * 2 : 16; inc_dirs = (char **) ct_grow(inc_dirs, (size_t) inc_dirs_cap * sizeof *inc_dirs); }
    inc_dirs[n_inc++] = (char *)d;
}
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
void flex_lex_open(Lex *lx, FILE *f, const char *fname) {
    yyscan_t sc;
    yylex_init(&sc);
    yy_switch_to_buffer(yy_create_buffer(f, YY_BUF_SIZE, sc), sc);
    lineno = 1;
    lx->_scanner = sc;
    lx->_extra   = NULL;
    (void)fname;
}
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
#define SNO_END_NONE   ((void *)0)
#define SNO_END_ARMED  ((void *)1)
#define SNO_END_CLOSED ((void *)2)
int sno_end_lineno = 0;
Token flex_lex_next(Lex *lx) {
    yyscan_t sc = (yyscan_t)lx->_scanner;
    for (;;) {
        int r;
        if (lx->_extra == SNO_END_CLOSED) { Token e; e.kind = T_EOF; e.sval = NULL; e.ival = 0; e.dval = 0.0; e.lineno = lineno; return e; }
        r = yylex(sc);
        Token t;
        t.lineno = lineno;
        t.ival   = 0;
        t.dval   = 0.0;
        t.sval   = NULL;
        t.kind   = r;
        if (r == T_STMT_END && lx->_extra == SNO_END_ARMED) { lx->_extra = SNO_END_CLOSED; sno_end_lineno = lineno; }
        switch (r) {
        case T_EOF:
            t.kind = T_EOF; return t;
        case T_LABEL:
            t.sval = intern(strbuf);
            t.ival = strcmp(strbuf,"END")==0 ? 1 : 0;
            t.lineno = g_stmt_pos.lineno;
            if (t.ival) lx->_extra = SNO_END_ARMED;
            return t;
        case T_IDENT: case T_END: case T_KEYWORD:
        case T_FUNCTION:
        case T_GOTO_S: case T_GOTO_F:
            t.sval = intern(strbuf);
            return t;
        case T_STR:
            t.sval = intern(strbuf);
            return t;
        case T_INT:
            t.ival = atol(strbuf);
            return t;
        case T_REAL:
            t.sval = intern(strbuf);
            { extern int rt_gtn_real(const char *, long, double *); char *_ne = (char *)0; errno = 0; double _rv = 0.0;
              if (!rt_gtn_real(strbuf, (long)strlen(strbuf), &_rv)) _rv = strtod(strbuf, &_ne);
              if (!isfinite(_rv)) { sno_error(lineno, "syntax error: invalid numeric item"); _rv = 0.0; }
              t.dval = _rv; }
            return t;
        default:
            return t;
        }
    }
}
